EXECUTE IMMEDIATE :command;
LET caller_ai_status VARCHAR := 'DISABLED'; IF ($WORKSPACE_AI) THEN BEGIN
command := 'GRANT CALLER USE AI FUNCTION AI_COMPLETE ON ACCOUNT TO ROLE ' || CHR(34) || REPLACE(runtime_role,CHR(34),CHR(34)||CHR(34)) || CHR(34); EXECUTE IMMEDIATE :command;
command := 'GRANT CALLER USAGE ON DATABASE SNOWFLAKE TO ROLE ' || CHR(34) || REPLACE(runtime_role,CHR(34),CHR(34)||CHR(34)) || CHR(34); EXECUTE IMMEDIATE :command;
command := 'GRANT CALLER PROGRAM USAGE ON DATABASE SNOWFLAKE TO ROLE ' || CHR(34) || REPLACE(runtime_role,CHR(34),CHR(34)||CHR(34)) || CHR(34); EXECUTE IMMEDIATE :command;
caller_ai_status := 'CONFIGURED';
EXCEPTION WHEN OTHER THEN caller_ai_status := 'ADMIN_ACTION_REQUIRED: ' || SQLERRM; END; END IF;
command := GET(statement_list,6)::VARCHAR;
command := REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(command,'${DATABASE}',database_name),'${WAREHOUSE}',warehouse_name),'${POOL}',pool_name),'${EAI}',eai_name),'${RUNTIME}',runtime_role),'${PROVISIONER}',provisioner_role);
EXECUTE IMMEDIATE :command;
