BEGIN command := GET(statement_list,148)::VARCHAR;
command := REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(command,'${DATABASE}',database_name),'${WAREHOUSE}',warehouse_name),'${POOL}',pool_name),'${EAI}',eai_name),'${RUNTIME}',runtime_role),'${PROVISIONER}',provisioner_role);
EXECUTE IMMEDIATE :command;BEGIN command := GET(statement_list,149)::VARCHAR;
command := REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(command,'${DATABASE}',database_name),'${WAREHOUSE}',warehouse_name),'${POOL}',pool_name),'${EAI}',eai_name),'${RUNTIME}',runtime_role),'${PROVISIONER}',provisioner_role);
EXECUTE IMMEDIATE :command; EXCEPTION WHEN OTHER THEN IF (SQLERRM NOT ILIKE '%already%live%') THEN RAISE; END IF; END;command := GET(statement_list,150)::VARCHAR;
command := REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(command,'${DATABASE}',database_name),'${WAREHOUSE}',warehouse_name),'${POOL}',pool_name),'${EAI}',eai_name),'${RUNTIME}',runtime_role),'${PROVISIONER}',provisioner_role);
EXECUTE IMMEDIATE :command; EXCEPTION WHEN OTHER THEN host_status := host_status || '; editable workspace unavailable: ' || SQLERRM; END;
LET app_found BOOLEAN := FALSE; BEGIN command := 'SHOW STREAMLITS IN SCHEMA ' || database_name || '.APP'; EXECUTE IMMEDIATE :command; app_found := (SELECT COUNT(*)=1 FROM TABLE(RESULT_SCAN(LAST_QUERY_ID())) WHERE "name"='EXECUTIVE_WORKSPACE'); EXCEPTION WHEN OTHER THEN app_found := FALSE; END; LET final_receipt RESULTSET := (SELECT IFF(:app_found AND :host_status NOT LIKE 'unavailable:%','APP_READY','APP_BUILD_FAILED') AS STATUS,IFF(:app_found AND :host_status NOT LIKE 'unavailable:%','https://app.snowflake.com/'||LOWER(CURRENT_ORGANIZATION_NAME())||'/'||LOWER(CURRENT_ACCOUNT_NAME())||'/#/streamlit-apps/'||:database_name||'.APP.EXECUTIVE_WORKSPACE',NULL) AS OPEN_APP_URL,IFF(:app_found,'OPEN THE APP: click OPEN_APP_URL. Review AI_STATUS and CALLER_AI_STATUS before relying on AI.',:host_status) AS NEXT_ACTION,:ai_status AS AI_STATUS,:caller_ai_status AS CALLER_AI_STATUS,:host_status AS HOST_STATUS,:source_revision AS SOURCE_REVISION); RETURN TABLE(final_receipt); END; $$;